// Verify Convex's HMAC signature over the RAW request body before trusting anything.
// Signed string: `${timestamp}.POST./lendloop-request.${rawBody}` (see convex/lib/hmac.ts).
const crypto = require('crypto');
const secret = $env.LENDLOOP_TO_N8N_SECRET;
const TOLERANCE_SECONDS = 300;
const item = $input.first();
const headers = item.json.headers || {};
const timestamp = String(headers['x-lendloop-timestamp'] || '');
const signature = String(headers['x-lendloop-signature'] || '');

let raw = '';
if (item.binary && item.binary.data) {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  raw = buf.toString('utf8');
}

function reject(reason) {
  console.warn('[lendloop] rejected request webhook:', reason);
  return [{ json: { accept: false, httpStatus: reason === 'secret_not_configured' ? 503 : 401, reason } }];
}

if (!secret) return reject('secret_not_configured');
if (!timestamp || !signature) return reject('missing_headers');
const m = /^sha256=([0-9a-f]{64})$/.exec(signature);
if (!m) return reject('malformed_signature');
if (!/^\d{1,12}$/.test(timestamp) || Math.abs(Date.now() / 1000 - Number(timestamp)) > TOLERANCE_SECONDS) {
  return reject('stale_timestamp');
}
const expected = crypto.createHmac('sha256', secret)
  .update(`${timestamp}.POST./lendloop-request.${raw}`)
  .digest();
const given = Buffer.from(m[1], 'hex');
if (given.length !== expected.length || !crypto.timingSafeEqual(given, expected)) {
  return reject('signature_mismatch');
}

let payload;
try { payload = JSON.parse(raw); } catch (e) { return reject('invalid_json'); }

// Replay / retry guard: remember recent deliveryIds (persists for active workflows).
const seen = $getWorkflowStaticData('global');
seen.deliveries = seen.deliveries || {};
if (seen.deliveries[payload.deliveryId]) {
  return [{ json: { accept: false, httpStatus: 200, reason: 'duplicate', deliveryId: payload.deliveryId } }];
}
seen.deliveries[payload.deliveryId] = Date.now();
const keys = Object.keys(seen.deliveries);
if (keys.length > 500) keys.slice(0, keys.length - 500).forEach((k) => delete seen.deliveries[k]);

// Pass on only the fields the notification needs (no headers, no raw body).
const { deliveryId, event, requestId, status, toolName, startDate, endDate, recipient } = payload;
return [{ json: { accept: true, deliveryId, event, requestId, status, toolName, startDate, endDate, recipient } }];

// Mock notification: builds the message and logs it. Swap this node for an
// Email (SMTP/Resend) or Slack node in production. Uses only the fields it needs.
const p = $input.first().json;
const range = `${p.startDate} to ${p.endDate}`;
const subjects = {
  created: `New request to borrow your ${p.toolName}`,
  approved: `Your request for the ${p.toolName} was approved`,
  declined: `Your request for the ${p.toolName} was declined`,
  returned: `${p.toolName} marked as returned`,
};
const bodies = {
  created: `A neighbour asked to borrow your ${p.toolName} (${range}). Open LendLoop to approve or decline.`,
  approved: `Good news: you can borrow the ${p.toolName} (${range}). Please return it by ${p.endDate}.`,
  declined: `Your request for the ${p.toolName} (${range}) was declined. Try another date or tool.`,
  returned: `The loan of the ${p.toolName} (${range}) has been marked as returned. Thanks!`,
};
const notification = {
  channel: p.recipient?.email ? 'mock-email' : 'log-only (no email on file)',
  to: p.recipient?.email ?? null,
  recipientName: p.recipient?.name,
  subject: subjects[p.event] ?? 'LendLoop update',
  text: `Hi ${p.recipient?.name ?? 'there'}, ${bodies[p.event] ?? ''}`,
};
console.log('[lendloop] MOCK NOTIFICATION', JSON.stringify(notification));
return [{ json: { ...p, notification, notifiedAt: new Date().toISOString() } }];

// HMAC-SHA256 over `${timestamp}.${METHOD}.${path}.${body}` (see convex/lib/hmac.ts).
// The secret comes from the n8n host environment, never from this workflow JSON.
const crypto = require('crypto');
const secret = $env.N8N_TO_LENDLOOP_SECRET;
if (!secret) throw new Error('N8N_TO_LENDLOOP_SECRET is not set on the n8n host');
function sign(method, path, body) {
  const timestamp = String(Math.floor(Date.now() / 1000));
  const hex = crypto.createHmac('sha256', secret)
    .update(`${timestamp}.${method}.${path}.${body}`)
    .digest('hex');
  return { timestamp, signature: `sha256=${hex}` };
}

// Idempotent write-back: the deliveryId is the dedupe key, so retries are harmless.
const p = $input.first().json;
const body = JSON.stringify({
  requestId: p.requestId,
  type: 'request_notification',
  dedupeKey: p.deliveryId,
  recipientRole: p.recipient?.role,
});
return [{ json: { body, ...sign('POST', '/n8n/events', body) } }];
